// Font bytes embedded at build time — no file system dependency in serverless
// Source: @fontsource/lato (700 bold) + @fontsource/libre-baskerville (400 regular + italic)
// WOFF format (zlib, reliably parsed by @pdf-lib/fontkit in all environments)
export const LATO_BOLD_WOFF    = Buffer.from('', 'base64');
export const LIBRE_REGULAR_WOFF = Buffer.from('', 'base64');
export const LIBRE_ITALIC_WOFF  = Buffer.from('', 'base64');
